@app.post("/refunds", response_model=RefundResponse, status_code=200)
async def request_refund(
        refund_request: RefundRequest,
        user_id: str = Query(..., description="User ID requesting the refund"),
        db: Session = Depends(get_db)
):
    """
    Process refund and release seat

    Steps:
    1. Validate booking belongs to user
    2. Check booking is refundable (not already refunded)
    3. Process refund with payment gateway
    4. Update booking status to REFUNDED
    5. Update payment status to REFUNDED
    6. RELEASE SEAT - change status to AVAILABLE
    7. Clear booked_by and booked_at
    """

    # Step 1: Get booking
    booking = db.query(Booking).filter(
        Booking.booking_id == refund_request.booking_id
    ).first()

    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")

    # Step 2: Verify ownership
    if str(booking.user_id) != user_id:
        raise HTTPException(
            status_code=403,
            detail="Not authorized to refund this booking"
        )

    # Step 3: Check if already refunded
    if booking.status == BookingStatus.REFUNDED:
        raise HTTPException(status_code=400, detail="Booking already refunded")

    if booking.status != BookingStatus.CONFIRMED:
        raise HTTPException(
            status_code=400,
            detail=f"Cannot refund booking with status: {booking.status.value}"
        )

    # Step 4: Get payment record
    payment = db.query(Payment).filter(
        Payment.booking_id == booking.booking_id
    ).first()

    if not payment:
        raise HTTPException(status_code=404, detail="Payment record not found")

    if payment.status != PaymentStatus.COMPLETED:
        raise HTTPException(
            status_code=400,
            detail="Cannot refund incomplete payment"
        )

    try:
        # Step 5: Process refund with payment gateway
        refund_success, refund_response = MockPaymentGateway.process_refund(
            transaction_id=payment.gateway_transaction_id,
            amount=float(payment.amount),
            reason=refund_request.reason
        )

        if not refund_success:
            raise HTTPException(
                status_code=400,
                detail=f"Refund failed: {refund_response.get('error')}"
            )

        # Step 6: Update payment status
        payment.status = PaymentStatus.REFUNDED
        payment.refunded_at = datetime.utcnow()
        payment.refund_reason = refund_request.reason
        payment.refund_transaction_id = refund_response.get("refund_id")

        # Step 7: Update booking status
        booking.status = BookingStatus.REFUNDED
        booking.updated_at = datetime.utcnow()

        # Step 8: RELEASE THE SEAT - Critical step!
        seat = db.query(Seat).filter(Seat.seat_id == booking.seat_id).first()

        if seat:
            seat.status = SeatStatus.AVAILABLE  # Back to available
            seat.booked_by = None  # Clear owner
            seat.booked_at = None  # Clear timestamp

        # Step 9: Commit all changes atomically
        db.commit()
        db.refresh(booking)
        db.refresh(payment)

        return RefundResponse(
            booking_id=str(booking.booking_id),
            payment_id=str(payment.payment_id),
            refund_amount=float(payment.amount),
            status="refunded",
            refund_transaction_id=payment.refund_transaction_id,
            seat_released=True,
            message="Refund processed successfully and seat has been released"
        )

    except HTTPException:
        db.rollback()
        raise
    except Exception as e:
        db.rollback()
        raise HTTPException(status_code=500, detail=f"Refund failed: {str(e)}")


