@app.websocket("/ws/events/{event_id}")
async def websocket_endpoint(websocket: WebSocket, event_id: str):
    """
    WebSocket endpoint for real-time seat availability updates

    Usage:
        const ws = new WebSocket('ws://localhost:8000/ws/events/{event_id}');

        ws.onmessage = (event) => {
            const data = JSON.parse(event.data);
            console.log('Seat update:', data);
        };

    Message Types:
    - connected: Initial connection confirmation
    - seat_update: Seat status changed (booked/available)
    - booking_created: New booking created
    - refund_processed: Booking refunded, seat released
    """
    await manager.connect(websocket, event_id)

    try:
        while True:
            # Keep connection alive and handle incoming messages
            data = await websocket.receive_text()

            # Handle ping/pong for connection health
            if data == "ping":
                await websocket.send_text("pong")
            else:
                # Echo back for debugging
                await manager.send_personal_message(
                    {"type": "echo", "message": data},
                    websocket
                )

    except WebSocketDisconnect:
        manager.disconnect(websocket, event_id)
        logging.info(f"WebSocket disconnected for event {event_id}")
    except Exception as e:
        logging.error(f"WebSocket error: {e}")
        manager.disconnect(websocket, event_id)


@app.get("/ws/stats")
async def websocket_stats():
    """Get WebSocket connection statistics"""
    return {
        "total_connections": manager.get_total_connections(),
        "connections_by_event": {
            event_id: manager.get_connection_count(event_id)
            for event_id in manager.active_connections.keys()
        }
    }


@app.post("/refunds", response_model=RefundResponse, status_code=200)
async def request_refund(
        refund_request: RefundRequest,
        user_id: str = Query(..., description="User ID requesting the refund"),
        db: Session = Depends(get_db)
):
    """Process refund and broadcast seat release via WebSocket"""

    # Call async process_refund method
    result = await PaymentService.process_refund(
        db=db,
        booking_id=str(refund_request.booking_id),
        user_id=user_id,
        reason=refund_request.reason
    )

    return RefundResponse(**result)

